<script setup>
import{computed,onMounted,ref}from'vue';import{AlertTriangle,CheckCircle2,Link2,Play,RotateCcw,ShieldCheck,Wrench}from'@lucide/vue';import{createLocalAdapterSession,getLocalAdapterCatalog,getLocalAdapterSession,listLocalAdapterSessions,runLocalAdapterAction}from'../api'
const catalog=ref(null),sessions=ref([]),s=ref(null),params=ref({}),fault=ref('sensor_timeout'),diagnosis=ref('传感器通道超时'),recovery=ref('restart_sensor_channel'),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('')
const adapter=computed(()=>catalog.value?.items?.[0]);function msg(e,f){const d=e?.response?.data?.detail;return d?.message||(typeof d==='string'?d:'')||e?.message||f}function apply(x){s.value=x;params.value={...x.parameters};sessions.value=sessions.value.map(i=>i.id===x.id?x:i);if(!sessions.value.some(i=>i.id===x.id))sessions.value.unshift(x)}
async function load(){try{const[c,l]=await Promise.all([getLocalAdapterCatalog(),listLocalAdapterSessions()]);catalog.value=c;sessions.value=l.items;params.value=Object.fromEntries(Object.entries(c.items[0].parameters).map(([k,v])=>[k,v.default]));if(l.items.length)apply(await getLocalAdapterSession(l.items[0].id))}catch(e){error.value=msg(e,'本地适配器加载失败')}finally{loading.value=false}}
async function create(){busy.value=true;try{apply(await createLocalAdapterSession({title:'视觉质检技能训练',adapter_id:adapter.value.id,credential_placeholder:'DEMO-LOCAL-ONLY',parameters:params.value}));notice.value='本地模拟会话已创建，尚未连接。'}catch(e){error.value=msg(e,'创建失败')}finally{busy.value=false}}
async function act(action,extra={}){busy.value=true;error.value='';try{apply(await runLocalAdapterAction(s.value.id,{action,expected_lock_version:s.value.lock_version,idempotency_key:`adapter-${action}-${Date.now()}`,parameters:action==='configure'?params.value:null,fault_type:extra.fault_type||'none',diagnosis:extra.diagnosis||'',recovery_action:extra.recovery_action||''}));notice.value=`动作 ${action} 已记录` }catch(e){error.value=msg(e,'操作失败')}finally{busy.value=false}}
function setRecovery(){const f=adapter.value.faults.find(x=>x.id===fault.value);recovery.value=f?.recovery||''}onMounted(load)
</script>
<template><main class="adapter" data-testid="local-adapter-workspace"><header><div><p class="eyebrow">LOCAL ENTERPRISE SIMULATION</p><h1>企业实验台本地适配器</h1><p>在不连接真实设备的前提下训练参数配置、故障诊断与恢复。</p></div><div class="boundary"><ShieldCheck :size="18"/><strong>本地模拟环境</strong><small>无网络 · 无真实设备 · 无真实凭证</small></div></header><p v-if="error" class="notice error">{{error}}</p><p v-if="notice" class="notice ok">{{notice}}</p><p v-if="loading" class="notice">正在恢复模拟会话...</p>
<div v-else class="grid"><aside><b>会话</b><button v-for="x in sessions" :key="x.id" :class="{active:s?.id===x.id}" @click="getLocalAdapterSession(x.id).then(apply)"><strong>{{x.title}}</strong><small>{{x.status}}</small></button><p v-if="!sessions.length">尚无会话。</p></aside><section><div class="adapter-head"><div><h2>{{adapter.title}}</h2><p>{{adapter.description}}</p></div><span>凭证占位：{{adapter.credential_example}}</span></div>
<div class="params"><label v-for="(d,k) in adapter.parameters" :key="k"><span>{{d.label}} <b>{{params[k]}}</b></span><input v-model.number="params[k]" type="range" :aria-label="d.label" :min="d.minimum" :max="d.maximum" :step="d.step"/><small>{{d.minimum}} 至 {{d.maximum}}</small></label></div>
<div v-if="!s" class="actions"><button class="primary" @click="create"><Link2 :size="15"/>创建本地会话</button></div><template v-else><div class="status" data-testid="adapter-status"><article><span>环境</span><strong>本地模拟</strong></article><article><span>状态</span><strong>{{s.status}}</strong></article><article><span>活动故障</span><strong>{{s.active_fault}}</strong></article><article><span>锁版本</span><strong>{{s.lock_version}}</strong></article></div>
<div class="actions"><button v-if="s.status==='disconnected'" class="primary" @click="act('connect')"><Link2 :size="15"/>连接模拟器</button><button v-if="['connected','recovered','passed'].includes(s.status)" @click="act('configure')"><Wrench :size="15"/>应用参数</button><button v-if="s.status==='connected'" class="primary" @click="act('run')"><Play :size="15"/>运行</button><button v-if="s.status==='recovered'" class="primary" @click="act('rerun')"><Play :size="15"/>恢复后重跑</button><button v-if="s.status==='running'" class="primary" @click="act('submit')"><CheckCircle2 :size="15"/>隐藏验收</button><button @click="act('reset')"><RotateCcw :size="15"/>重置</button></div>
<div v-if="s.metrics&&Object.keys(s.metrics).length" class="metrics"><article v-for="(v,k) in s.metrics" :key="k"><span>{{k}}</span><strong>{{v}}</strong></article></div>
<div class="fault"><div><AlertTriangle :size="17"/><strong>受控故障演练</strong></div><template v-if="s.status==='connected'"><select v-model="fault" @change="setRecovery"><option v-for="f in adapter.faults" :key="f.id" :value="f.id">{{f.label}}</option></select><button @click="act('inject_fault',{fault_type:fault})">注入故障</button></template><template v-if="s.status==='failed'"><input v-model="diagnosis" aria-label="诊断说明"/><select v-model="recovery"><option v-for="f in adapter.faults" :key="f.recovery" :value="f.recovery">{{f.recovery}}</option></select><button @click="act('diagnose',{diagnosis,recovery_action:recovery})">提交诊断</button></template><button v-if="s.status==='diagnosed'&&s.recovery_verified" @click="act('recover')">执行恢复</button><span v-if="s.status==='diagnosed'&&!s.recovery_verified">恢复动作不匹配，请修正诊断。</span></div>
<div v-if="s.hidden_acceptance?.passed" class="pass"><CheckCircle2 :size="18"/><strong>隐藏验收 {{s.hidden_acceptance.passed_count}}/{{s.hidden_acceptance.total_count}}</strong><span>{{s.hidden_acceptance.checker_version}}</span></div>
<div class="events"><h3>不可变动作轨迹</h3><div v-for="e in s.events" :key="e.id" data-testid="adapter-event"><b>{{e.action}}</b><span>{{e.from_status}} → {{e.to_status}}</span><small>{{e.snapshot.environment}}</small></div></div></template></section></div></main></template>
<style scoped>.adapter{max-width:1160px;margin:auto;color:#26332b}.adapter header{display:flex;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:1px solid #dbe2dc}.eyebrow{margin:0 0 7px;font-size:10px;font-weight:800;color:#456b52}.adapter h1{margin:0;font-size:23px;letter-spacing:0}.adapter header p:last-child{margin:7px 0;color:#68746c;font-size:12px}.boundary{display:grid;grid-template-columns:auto 1fr;align-content:center;min-width:240px;padding:12px;border:1px solid #cfe0d4;background:#edf7f0}.boundary svg{grid-row:1/3;margin-right:8px}.boundary strong{font-size:12px}.boundary small{font-size:9px;color:#6f7c73}.notice{padding:10px;font-size:11px;background:#f4f6f4}.error{background:#fff1ef;color:#88483f}.ok{background:#edf7f0;color:#356044}.grid{display:grid;grid-template-columns:210px 1fr;gap:14px;margin-top:15px}.grid>aside,.grid>section{border:1px solid #dce2de;background:white;padding:13px}.grid aside>button{display:flex;justify-content:space-between;width:100%;padding:10px 5px;border:0;border-bottom:1px solid #edf0ee;background:white;font-size:9px}.grid aside>button.active{background:#eef5f0}.adapter-head{display:flex;justify-content:space-between;gap:15px}.adapter-head h2{margin:0;font-size:17px}.adapter-head p{font-size:10px;color:#6f7b73}.adapter-head>span{padding:8px;background:#f3f6f4;font-size:9px}.params{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:13px;background:#f6f8f6}.params label span{display:flex;justify-content:space-between;font-size:9px}.params input{width:100%;accent-color:#426b50}.params small{font-size:8px;color:#849087}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.actions button,.fault button{display:inline-flex;align-items:center;gap:5px;min-height:34px;padding:0 10px;border:1px solid #ccd6ce;background:white;font-size:10px}.actions .primary{background:#355b42;color:white}.status,.metrics{display:grid;grid-template-columns:repeat(4,1fr);margin-top:12px;border:1px solid #dce3de}.status article,.metrics article{padding:10px;border-right:1px solid #e3e8e4}.status span,.metrics span{display:block;color:#7a867e;font-size:8px}.status strong,.metrics strong{display:block;margin-top:4px;font-size:11px;overflow-wrap:anywhere}.fault{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px;padding:11px;background:#fff8f3;border:1px solid #ead8ca;font-size:9px}.fault>div{display:flex;gap:5px;margin-right:auto}.fault input,.fault select{height:32px;border:1px solid #d8d0ca;background:white}.pass{display:flex;gap:8px;align-items:center;margin-top:10px;padding:11px;background:#edf7f0;color:#356044;font-size:10px}.pass span{margin-left:auto}.events{margin-top:13px}.events h3{font-size:11px}.events>div{display:grid;grid-template-columns:100px 1fr auto;padding:7px;border-top:1px solid #edf0ee;font-size:9px}@media(max-width:800px){.adapter header{flex-direction:column}.boundary{min-width:0}.grid,.params{grid-template-columns:1fr}.grid>aside{max-height:140px;overflow:auto}.status,.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:430px){.adapter-head{flex-direction:column}.status,.metrics{grid-template-columns:1fr}.events>div{grid-template-columns:75px 1fr}.events small{grid-column:2}}</style>
